-- Separate public event replica; private event content is never retained.
CREATE TABLE IF NOT EXISTS open_house_state(source TEXT PRIMARY KEY,phase TEXT NOT NULL DEFAULT 'initial',timestamp TEXT,baseline TEXT,next_url TEXT,last_attempt INTEGER NOT NULL DEFAULT 0,last_complete INTEGER NOT NULL DEFAULT 0,retry_after INTEGER NOT NULL DEFAULT 0,lease TEXT,lease_until INTEGER NOT NULL DEFAULT 0,examined INTEGER NOT NULL DEFAULT 0,failure TEXT,diagnostics TEXT NOT NULL DEFAULT '{}');CREATE TABLE IF NOT EXISTS open_house_records(source TEXT NOT NULL,id TEXT NOT NULL,modified TEXT NOT NULL,version TEXT NOT NULL,listing_key TEXT,listing_number TEXT,start_at TEXT,end_at TEXT,public INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(source,id));CREATE INDEX IF NOT EXISTS open_houses_key ON open_house_records(source,listing_key,public,end_at);CREATE INDEX IF NOT EXISTS open_houses_number ON open_house_records(source,listing_number,public,end_at);
